SELECT po.product_uid AS "productId" , po.product_option_id AS "optionId" , DENSE_RANK() OVER (ORDER BY po.product_color) AS "colorId" , po.product_color AS "colorName" , po.product_size AS "sizeId" , po.product_size::text AS "sizeName" , po.product_quantity AS "stock" FROM product_option_tb po WHERE po.product_uid IN
#{productId}
ORDER BY po.product_uid, po.product_option_id

SELECT COUNT(*)
  FROM "cart" c
 WHERE c.member_id = #{memberId}

SELECT c.cart_quantity
  FROM "cart" c
 WHERE c.member_id = #{memberId}
   AND c.stock_id = #{stockId}
 LIMIT 1

SELECT c.cart_id
  FROM "cart" c
 WHERE c.member_id = #{memberId}
   AND c.stock_id = #{stockId}
 LIMIT 1

mapper.update:
UPDATE "cart"
   SET cart_quantity = #{quantity}
 WHERE member_id = #{memberId}
   AND stock_id = #{stockId}

UPDATE "cart"
   SET stock_id = #{newStockId},
       cart_quantity = #{quantity}
 WHERE cart_id = #{cartId}
   AND member_id = #{memberId}

